
use anyhow::Result; use image::{GrayImage, Luma}; const A9_W: u32 = 437; const A9_H: u32 = 614; const MARKER_SIZE: u32 = 20; pub fn render(payload: &[u8], path: &str) -> Result<()> { let mut img = GrayImage::from_pixel(A9_W, A9_H, Luma([255u8])); draw_marker(&mut img, 0, 0); draw_marker(&mut img, A9_W - MARKER_SIZE, 0); draw_marker(&mut img, 0, A9_H - MARKER_SIZE); draw_marker(&mut img, A9_W - MARKER_SIZE, A9_H - MARKER_SIZE); let start_x = MARKER_SIZE + 5; let start_y = MARKER_SIZE + 5; let end_x = A9_W - MARKER_SIZE - 5; let end_y = A9_H - MARKER_SIZE - 5; let mut bit_idx = 0; for y in start_y..end_y { for x in start_x..end_x { if bit_idx / 8 >= payload.len() { break; } let bit = (payload[bit_idx / 8] >> (7 - (bit_idx % 8))) & 1; img.put_pixel(x, y, Luma([if bit == 0 { 0 } else { 255 }])); bit_idx += 1; } } img.save(path)?; Ok(()) } fn draw_marker(img: &mut GrayImage, x: u32, y: u32) { for dy in 0..MARKER_SIZE { for dx in 0..MARKER_SIZE { if x+dx < img.width() && y+dy < img.height() { img.put_pixel(x+dx, y+dy, Luma([0])); } } } }